def transform(grid):
    g = np.array(grid)
    out = g.copy()
    h, w = g.shape
    for y in range(h):
        for x in range(w):
            if g[y, x] != 3:
                continue
            partners = []
            for dy, dx in ((-1, 0), (1, 0), (0, -1), (0, 1)):
                ny, nx = y + dy, x + dx
                if 0 <= ny < h and 0 <= nx < w and g[ny, nx] == 2:
                    partners.append((ny, nx))
            if partners:
                out[y, x] = 8
                for ny, nx in partners:
                    out[ny, nx] = 0
                emit(out, f"The 3 at ({y},{x}) touches a 2 at {partners}: the pair merges, the 3 becomes 8 and the 2 is erased.")
    emit(out, "All touching 3-2 pairs are merged; isolated 2s, 3s and the 5s stay unchanged.")
    return out
